#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int i, long long value) {
        for (; i <= n; i += i & -i)
            bit[i] += value;
    }

    long long sum(int i) const {
        long long result = 0;
        for (; i > 0; i -= i & -i)
            result += bit[i];
        return result;
    }
};

struct LineValues {
    long long atLeft;
    long long atRight;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long X1, X2;
    cin >> N >> X1 >> X2;

    vector<LineValues> lines(N);
    vector<long long> rightValues;
    rightValues.reserve(N);

    for (int i = 0; i < N; ++i) {
        long long A, B;
        cin >> A >> B;
        lines[i] = {A * X1 + B, A * X2 + B};
        rightValues.push_back(lines[i].atRight);
    }

    sort(lines.begin(), lines.end(), [](const LineValues& a, const LineValues& b) {
        return a.atLeft < b.atLeft;
    });

    sort(rightValues.begin(), rightValues.end());
    rightValues.erase(unique(rightValues.begin(), rightValues.end()), rightValues.end());

    Fenwick fenwick(static_cast<int>(rightValues.size()));
    long long inserted = 0;
    long long answer = 0;

    for (int i = 0; i < N;) {
        int j = i + 1;
        while (j < N && lines[j].atLeft == lines[i].atLeft)
            ++j;

        long long groupSize = j - i;
        answer += groupSize * (groupSize - 1) / 2;

        for (int k = i; k < j; ++k) {
            int index = lower_bound(rightValues.begin(), rightValues.end(),
                                    lines[k].atRight) - rightValues.begin() + 1;
            answer += inserted - fenwick.sum(index - 1);
        }

        for (int k = i; k < j; ++k) {
            int index = lower_bound(rightValues.begin(), rightValues.end(),
                                    lines[k].atRight) - rightValues.begin() + 1;
            fenwick.add(index, 1);
            ++inserted;
        }

        i = j;
    }

    cout << answer << '\n';
    return 0;
}
